#pragma once
#include <SDL2/SDL.h>
#include <stdint.h>

/*
 * SDL2 front-panel UI, laid out to match a real MS800 unit photo:
 * charcoal fascia, red 2-digit display, "DIGITAL WAVE SYNTHESIZER"
 * caption, power rocker, and 10 buttons in a 2x5 grid with the real
 * printed labels. The wordmark reads "CHEETAR MS800" on purpose.
 *
 *   CHANNEL   PATCH   ^   ^^   NEXT PARAM
 *   FUNCTION  PARAM   v   vv   ENTER
 *
 * (top row above each button, bottom row below — as on the real unit.)
 */

#include "panel_layout.h"   /* generated by tools/gen_panel_art.py */

#define BTN_COLS 5

/* Logical button indices 1-10, matching the firmware's front-panel scan
   order (see bus.c's row-select decode) and bus_button_state[]. These do
   NOT run in the same order as the on-screen 2x5 grid — the scan matrix
   interleaves rows/columns differently from the visual layout.
   Verified against the firmware disassembly and by empirical testing
   (each index pressed alone from a clean boot, watching the display and
   relevant zero-page state):
     1  UP           - increments displayed value by 1
     2  DOWN         - decrements displayed value by 1
     3  PARAM        - $E369 block: sets up a parameter-edit counter
                        against the per-patch max table at $FDF2
     4  CHANNEL      - $E307 block: max value 16 (MIDI channels 1-16)
     5  FUNCTION     - $E362 block: max value 10 (the 10 printed panel
                        functions: PATCH EDIT..TONE COPY)
     6  UP UP        - increments displayed value by 10
     7  DOWN DOWN    - decrements displayed value by 10
     8  NEXT PARAM   - $E44E block: increments the $4C step counter,
                        clamped to the per-patch max ($FDF2)
     9  PATCH        - $E334 block: max value 99, addresses into the
                        $1Cxx patch RAM area
     10 ENTER        - $E2F9 block: clears display/edit state (confirm) */
enum {
    BTN_UP = 1,
    BTN_DOWN,
    BTN_PARAM,
    BTN_CHANNEL,
    BTN_FUNCTION,
    BTN_UP_UP,
    BTN_DOWN_DOWN,
    BTN_NEXT_PARAM,
    BTN_PATCH,
    BTN_ENTER,
};

void ui_panel_init(SDL_Renderer *ren);
void ui_panel_draw(SDL_Renderer *ren, uint8_t display_byte, int powered_on);

/* Returns the logical button index (1-10) hit at (x,y), or 0 if none. */
int ui_panel_hit_test_button(int x, int y);

/* Returns 1 if (x,y) is within the power switch hit area. */
int ui_panel_hit_test_power(int x, int y);
